tools.example:
SET SNAP_LENGTH 20mil;
SET PALETTE BLACK; WINDOW;
SET XREF_LABEL_FORMAT '%F%N/%S.%C%R';

SET WIRE_BEND 2;
SET USED_LAYERS 1 16 17 18 19 20 21 23 25 27 29 31 44 45 51;
SET OBSTACLE_MODE WALKAROUND;
SET WIDTH_MENU 0.2mm 0.3mm 0.5mm 1mm;
CHANGE DRILL 0.4mm;

BRD:
GRID MM 0.5;
DISPLAY = 'Preset_Top' None 1 17 18 19 20 21 23 25 39 41 51;
SCH:
GRID DEFAULT;
CHANGE WIDTH 0.006in;

SET Interface.PreferredUnit 2;
SET Option.DrawUnprocessedPolygonEdgesContinuous 1;
WINDOW;

GRID MM 1;
CHANGE LAYER DIMENSION;
LINE 0 (0 0) (100 0) (100 80) (0 80) (0 0);
GRID LAST;

OPEN mylib.lbr;
EDIT SOT23-5.fpt;
EDIT LDO-3V3.dev;

SET DESIGN_MANAGER ON;
SET INSPECTOR TOGGLE;
SET SHEETS OFF;

SET SELECTTYPES HOLE WIRE VIA;
SET SELECTTYPES ALL -AIRWIRE;
SET SELECTLAYERS NONE TOP BOTTOM 20;
SET SELECTLAYERS NONE PRESET_TOP;

GRID 1 10;
SET BEEP OFF;
DISPLAY TOP PINS VIAS
WINDOW;          # redraw
WINDOW FIT       # complete without ';'
CHANGE WIDTH 0.3mm;

MOVE R1 (@);
MARK (10 10);
LINE 0.2 (R 0 0) (R 20 0) (P 20 90);
(CR> 1 2)     # Ctrl + right click at (1 2) relative to the mark
